<?php
declare(strict_types=1);
const BASE='https://beyondspacetime.org';
const ARC='https://arcsecs.com/';
function h($x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function j($x):string{return json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}
function num($x):string{if(!is_numeric($x))return (string)$x;$v=(float)$x;return $v==0?'0':(abs($v)<.0001||abs($v)>=1e6?sprintf('%.5e',$v):rtrim(rtrim(sprintf('%.6f',$v),'0'),'.'));}
function page_start(string $title,string $desc,string $path,string $type='WebPage',bool $noindex=false,array $extra=[]):void{
 $full=$path==='/'?'Beyond Spacetime | Explore the physical universe':$title.' | Beyond Spacetime';$url=BASE.$path;
 $graph=[['@type'=>'WebSite','@id'=>BASE.'/#site','url'=>BASE.'/','name'=>'Beyond Spacetime','inLanguage'=>'en','publisher'=>['@id'=>BASE.'/#publisher']],['@type'=>'Organization','@id'=>BASE.'/#publisher','name'=>'Beyond Spacetime','url'=>BASE.'/','logo'=>BASE.'/assets/compass.png','sameAs'=>[ARC]],['@type'=>$type,'@id'=>$url.'#page','url'=>$url,'name'=>$title,'description'=>$desc,'isPartOf'=>['@id'=>BASE.'/#site'],'inLanguage'=>'en','isAccessibleForFree'=>true,'relatedLink'=>ARC]];
 if($path!=='/'){$items=[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>BASE.'/']];if(str_starts_with($path,'/concepts/')&&$path!=='/concepts/')$items[]=['@type'=>'ListItem','position'=>2,'name'=>'Concepts','item'=>BASE.'/concepts/'];if(str_starts_with($path,'/labs/')&&$path!=='/labs/')$items[]=['@type'=>'ListItem','position'=>2,'name'=>'Labs','item'=>BASE.'/labs/'];$items[]=['@type'=>'ListItem','position'=>count($items)+1,'name'=>$title,'item'=>$url];$graph[]=['@type'=>'BreadcrumbList','itemListElement'=>$items];}
 $graph=array_merge($graph,$extra);
 ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($full)?></title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow, max-image-preview:large'?>"><link rel="canonical" href="<?=h($url)?>"><meta property="og:type" content="<?=$type==='Article'?'article':'website'?>"><meta property="og:title" content="<?=h($full)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h($url)?>"><meta property="og:image" content="<?=BASE?>/assets/hero.webp"><meta property="og:site_name" content="Beyond Spacetime"><meta property="og:image:alt" content="Beyond Spacetime cosmic banner"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="<?=h($full)?>"><meta name="twitter:description" content="<?=h($desc)?>"><meta name="twitter:image" content="<?=BASE?>/assets/hero.webp"><meta name="theme-color" content="#081222"><link rel="icon" href="/favicon.ico" type="image/x-icon"><link rel="apple-touch-icon" href="/assets/compass.png"><link rel="stylesheet" href="/assets/site.css?v=1.2.0"><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>$graph])?></script><script src="/assets/site.js?v=1.2.0" defer></script><script src="/assets/learning.js?v=1.2.0" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a href="/" class="brand"><img src="/assets/compass.png" width="39" height="39" alt=""><span>BEYOND<span class="brand-gold">SPACETIME</span><small>THE EXPLAINER PROJECT</small></span></a><nav aria-label="Main navigation"><?php foreach(['/explore/'=>'Explore 3D','/learn/'=>'Learn','/atlas/'=>'Atlas','/concepts/'=>'Concepts','/labs/'=>'Labs','/compare/'=>'Compare','/agents/'=>'Agents'] as $p=>$label):$active=$p==='/'?$path==='/':str_starts_with($path,$p);?><a href="<?=$p?>" <?=$active?'aria-current="page"':''?>><?=h($label)?></a><?php endforeach;?></nav><a class="nav-arc" href="<?=ARC?>read-book/">Read on ArcSecs <span aria-hidden="true">↗</span></a></div></header><main id="main" tabindex="-1" class="main">
 <?php if($path!=='/'):?><div class="crumb"><a href="/">Home</a> <span aria-hidden="true">/</span> <?php if($path!=='/concepts/'&&str_starts_with($path,'/concepts/')):?><a href="/concepts/">Concepts</a> / <?php elseif($path!=='/labs/'&&str_starts_with($path,'/labs/')):?><a href="/labs/">Labs</a> / <?php endif;?><span><?=h($title)?></span></div><?php endif;
}
function page_end():void{?><footer class="footer"><div><a class="brand" href="/"><img src="/assets/compass.png" width="35" height="35" alt=""><span>BEYOND<span class="brand-gold">SPACETIME</span></span></a><p>An independent learning companion to the ArcSecs research program. Hypotheses are not established discoveries.</p></div><div><h2>Explore</h2><a href="/explore/">Immersive 3D exploration</a><a href="/concepts/">Concept guides</a><a href="/labs/">Interactive labs</a><a href="/learn/">Learning paths</a><a href="/atlas/">Concept atlas</a><a href="/glossary/">Glossary</a><a href="/compare/">Compare experiments</a><a href="/methods/">Evidence standards</a></div><div><h2>Authoritative sources</h2><a href="<?=ARC?>read-book/">Read the book ↗</a><a href="<?=ARC?>read-scientific-paper/">Scientific paper ↗</a><a href="<?=ARC?>research-library/">Research library ↗</a></div><div><h2>Discovery</h2><a href="/agents/">Agent interface</a><a href="/about/">About & privacy</a><a href="/sitemap.xml">Sitemap</a><a href="/llms.txt">Machine-readable guide</a></div><p class="footnote">BeyondSpacetime.org · Native, self-contained software · No trackers or external runtime dependencies</p></footer></main></body></html><?php }
function topic_card(array $t):void{?><article class="tile"><span class="eyebrow"><?=h($t['category'])?></span><h3><a href="/concepts/<?=h($t['slug'])?>/"><?=h($t['title'])?></a></h3><p><?=h($t['summary'])?></p><a class="text-link" href="/concepts/<?=h($t['slug'])?>/">Explore concept <span aria-hidden="true">→</span></a></article><?php }
function lab_card(array $l):void{?><article class="tile lab-tile"><span class="eyebrow">Computational control</span><h3><a href="/labs/<?=h($l['id'])?>/"><?=h($l['title'])?></a></h3><p><?=h($l['description'])?></p><div class="formula small"><?=h($l['equation'])?></div><a class="text-link" href="/labs/<?=h($l['id'])?>/">Open experiment <span aria-hidden="true">→</span></a></article><?php }
function chart_svg(array $r,?array $other=null):string{$rows=$r['rows'];if(!$rows)return '';$domain=$other?array_merge($rows,$other['rows']):$rows;$xs=array_column($domain,0);$xmin=min($xs);$xmax=max($xs);$ys=[];foreach($domain as $row)foreach(array_slice($row,1) as $y)$ys[]=$y;$ymin=min(0,min($ys));$ymax=max(0,max($ys));if($ymin==$ymax)$ymax=$ymin+1;if($xmin==$xmax)$xmax=$xmin+1;$x=fn($a)=>52+($a-$xmin)/($xmax-$xmin)*660;$y=fn($a)=>265-($a-$ymin)/($ymax-$ymin)*230;$svg='<svg class="chart" viewBox="0 0 740 315" role="img" aria-label="'.h($r['xLabel'].' versus '.implode(', ',$r['series'])).'" xmlns="http://www.w3.org/2000/svg">';for($i=0;$i<=4;$i++){$Y=35+$i*57.5;$val=$ymax-($ymax-$ymin)*$i/4;$X=52+$i*165;$Xval=$xmin+($xmax-$xmin)*$i/4;$svg.='<line class="gridline" x1="52" y1="'.$Y.'" x2="712" y2="'.$Y.'"/><text x="46" y="'.($Y+4).'" text-anchor="end">'.h(num($val)).'</text><text x="'.$X.'" y="284" text-anchor="middle">'.h(num($Xval)).'</text>';}
 foreach($r['series'] as $i=>$name){$pts=[];foreach($rows as $row)$pts[]=sprintf('%.2f,%.2f',$x($row[0]),$y($row[$i+1]));$svg.='<polyline class="series series-'.$i.'" points="'.implode(' ',$pts).'"/>';}$svg.='<text x="382" y="308" text-anchor="middle">'.h($r['xLabel']).'</text></svg>';return $svg;}
function result_html(array $r):void{?><div class="metrics"><?php foreach($r['metrics'] as $m):?><div class="metric"><span><?=h($m['label'])?></span><strong><?=h(num($m['value']))?> <small><?=h($m['unit'])?></small></strong></div><?php endforeach;?></div><?php if($r['note']):?><p class="notice"><?=h($r['note'])?></p><?php endif;?><figure class="chart-box"><?=chart_svg($r)?><figcaption class="legend"><?php foreach($r['series'] as $i=>$s):?><span><i class="swatch series-<?=$i?>"></i><?=h($s)?></span><?php endforeach;?></figcaption></figure><details class="table-details"><summary>Numerical sample table (<?=count($r['rows'])?> rows)</summary><div class="table-scroll"><table><caption>Computed samples (first 12 and final row; full data in export)</caption><thead><tr><th scope="col"><?=h($r['xLabel'])?></th><?php foreach($r['series'] as $s):?><th scope="col"><?=h($s)?></th><?php endforeach;?></tr></thead><tbody><?php foreach(array_merge(array_slice($r['rows'],0,12),count($r['rows'])>12?[end($r['rows'])]:[]) as $row):?><tr><?php foreach($row as $n):?><td><?=h(num($n))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><?php }
